      const vars = opts.variables || ['x'];
      const list = Array.isArray(targets) ? targets : [targets];
      const slot = _equationErrorSlot(input);
      // Validated once, loudly, before anything is wired up.
      const appliers = list.map((t) => _resolveEqTarget(inputId, t));

      function apply(src) {
        try {
          // The dispatch is INSIDE the try as well: an error thrown while
          // applying (a target callback that throws, a handle mutated later)
          // would otherwise escape uncaught from the input event handler and
          // leave the figure stale with no visible reason.
          const fn = compileExpr(src, vars);
          for (const run of appliers) run(fn, src);
          if (typeof opts.onChange === 'function') opts.onChange(fn, src);
        } catch (e) {
          slot.textContent = e.message;
          slot.style.display = '';
          input.setAttribute('data-eq-valid', 'false');
          return false;
        }
        slot.textContent = '';
        slot.style.display = 'none';
        input.setAttribute('data-eq-valid', 'true');
        return true;
      }

      input.addEventListener('input', () => apply(input.value));
      apply(input.value);
      return { apply, input, errorSlot: slot };
    }

    /* ── 3D plotting ─────────────────────────────────────────────────────── */
    const _plot3d = new Map();

    function _disposeObject(obj) {
      obj.traverse?.(o => {
        o.geometry?.dispose?.();
        if (Array.isArray(o.material)) o.material.forEach(m => m.dispose?.());
        else o.material?.dispose?.();
      });
    }

    function _register3d(id, handle) {
      const prev = _plot3d.get(id);
      if (prev && prev !== handle) { scene.remove(prev.object); _disposeObject(prev.object); }
      _plot3d.set(id, handle);
      return handle;
    }

    function _resolveFn3d(value, vars) {
      return typeof value === 'function' ? value : compileExpr(value, vars);
    }

    /**
     * plotCurve3D(id, opts) → handle
     *   opts: { expr | fn, variables=['x'], domain=[-2,2], plane='xy'|'xz',
     *           samples=200, color=0x1f77b4 }
     * 'xy' maps t → (t, f(t), 0); 'xz' maps t → (t, 0, f(t)).
     */
    function plotCurve3D(id, opts = {}) {
      const vars = opts.variables || ['x'];
      const material = new THREE.LineBasicMaterial({ color: opts.color ?? 0x1f77b4 });
      const line = new THREE.Line(new THREE.BufferGeometry(), material);
      scene.add(line);
      const handle = {
        id,
        object: line,
        fn: opts.fn ? opts.fn : (opts.expr != null ? compileExpr(opts.expr, vars) : null),
        domain: opts.domain || [-2, 2],
        samples: opts.samples || 200,
        plane: opts.plane === 'xz' ? 'xz' : 'xy',
        setExpr(src) { this.fn = _resolveFn3d(src, vars); return this.sample(); },
        setFn(f) { this.fn = f; return this.sample(); },
        setDomain(dm) { this.domain = dm; return this.sample(); },
        remove() { scene.remove(line); _disposeObject(line); _plot3d.delete(id); },
        sample() {
          if (!this.fn) return this;
          const [a, b] = this.domain;
          const n = Math.max(2, this.samples | 0);
          const pts = [];
          for (let i = 0; i < n; i++) {
            const t = a + (b - a) * (i / (n - 1));
            let v;
            try { v = this.fn(t); } catch { v = NaN; }
            if (!Number.isFinite(v)) v = 0;
            pts.push(this.plane === 'xz' ? new THREE.Vector3(t, 0, v)
              : new THREE.Vector3(t, v, 0));
          }
          const old = line.geometry;
          line.geometry = new THREE.BufferGeometry().setFromPoints(pts);
          old?.dispose?.();
          return this;
        }
      };
      return _register3d(id, handle).sample();
    }

    /**
     * plotParametric3D(id, opts) → handle
     *   opts: { x, y, z, variables=['t'], tDomain=[0,1], samples=200, color }
     */
    function plotParametric3D(id, opts = {}) {
      const vars = opts.variables || ['t'];
      const material = new THREE.LineBasicMaterial({ color: opts.color ?? 0x1f77b4 });
      const line = new THREE.Line(new THREE.BufferGeometry(), material);
      scene.add(line);
      const handle = {
        id,
        object: line,
        fx: _resolveFn3d(opts.x ?? '0', vars),
        fy: _resolveFn3d(opts.y ?? '0', vars),
        fz: _resolveFn3d(opts.z ?? '0', vars),
        tDomain: opts.tDomain || [0, 1],
        samples: opts.samples || 200,
        setX(src) { this.fx = _resolveFn3d(src, vars); return this.sample(); },
        setY(src) { this.fy = _resolveFn3d(src, vars); return this.sample(); },
        setZ(src) { this.fz = _resolveFn3d(src, vars); return this.sample(); },
        remove() { scene.remove(line); _disposeObject(line); _plot3d.delete(id); },
        sample() {
          const [a, b] = this.tDomain;
          const n = Math.max(2, this.samples | 0);
          const pts = [];
          for (let i = 0; i < n; i++) {
            const t = a + (b - a) * (i / (n - 1));
            let x, y, z;
            try { x = this.fx(t); y = this.fy(t); z = this.fz(t); } catch { x = y = z = NaN; }
            if (Number.isFinite(x) && Number.isFinite(y) && Number.isFinite(z)) {
              pts.push(new THREE.Vector3(x, y, z));
            }
          }
          const old = line.geometry;
          line.geometry = new THREE.BufferGeometry().setFromPoints(pts);
          old?.dispose?.();
          return this;
        }
      };
      return _register3d(id, handle).sample();
    }

    /**
     * plotSurface(id, opts) → handle
     *   opts: { expr | fn, variables=['x','y'], xDomain=[-2,2], yDomain=[-2,2],
     *           segments=48, color=0x6699cc, wireframe=false }
     * Height is mapped to the world Y axis (the scaffold is y-up); the domain
     * spans world X and Z.
     */
    function plotSurface(id, opts = {}) {
      const vars = opts.variables || ['x', 'y'];
      const material = new THREE.MeshBasicMaterial({
        color: opts.color ?? 0x6699cc,
        wireframe: !!opts.wireframe,
        side: THREE.DoubleSide,
        transparent: true,
        opacity: opts.opacity ?? 0.85,
      });
      const mesh = new THREE.Mesh(new THREE.BufferGeometry(), material);
      scene.add(mesh);
      const handle = {
        id,
        object: mesh,
        fn: opts.fn ? opts.fn : (opts.expr != null ? compileExpr(opts.expr, vars) : null),
        xDomain: opts.xDomain || [-2, 2],
        yDomain: opts.yDomain || [-2, 2],
        segments: opts.segments || 48,
        setExpr(src) { this.fn = _resolveFn3d(src, vars); return this.sample(); },
        setFn(f) { this.fn = f; return this.sample(); },
        remove() { scene.remove(mesh); _disposeObject(mesh); _plot3d.delete(id); },
        sample() {
          if (!this.fn) return this;
          const [x0, x1] = this.xDomain;
          const [y0, y1] = this.yDomain;
          const seg = Math.max(1, this.segments | 0);
          const geom = new THREE.PlaneGeometry(x1 - x0, y1 - y0, seg, seg);
          const pos = geom.attributes.position;
          const cx = (x0 + x1) / 2, cy = (y0 + y1) / 2;
          for (let i = 0; i < pos.count; i++) {
            const px = pos.getX(i) + cx;
            const py = pos.getY(i) + cy;
            let h;
            try { h = this.fn(px, py); } catch { h = NaN; }
            if (!Number.isFinite(h)) h = 0;
            pos.setXYZ(i, px, h, py);
          }
          pos.needsUpdate = true;
          geom.computeVertexNormals();
          geom.computeBoundingBox();
          geom.computeBoundingSphere();
          const old = mesh.geometry;
          mesh.geometry = geom;
          old?.dispose?.();
          return this;
        }
      };
      return _register3d(id, handle).sample();
    }

    // @FIGURE_CODE_BEGIN
    // @FIGURE_CODE_END

    // Decide the panel layout once the generated UI exists. Runs last so it sees
    // the final #ui content; a setUiLayout() call in the block above wins.
    _autoUiLayout();

  </script>
</body>

</html>
--------------------------------------------------------------------------------

WHAT THE SCAFFOLD PROVIDES (already defined — use these, never re-declare them):
- Scale guide (orthographic camera, d=3 frustum half-height): keep main geometry within ±2 units in all axes. Typical sizes: cube side 1–2 units, arrow length 1–2, plane width 2–4, sphere radius 0.05–0.15.
- setCameraView({ projection, azimuthDeg, elevationDeg, rollDeg, axisScreenAngles, obliqueAngleDeg, depthScale, zoom, target, heightFraction, distanceScale }) — source-matched camera setup.
  heightFraction: fraction of viewport height the content should fill (default 0.5; use 0.65–0.75 to fill more). Omit zoom — the scaffold auto-fits from projected scene bounds.
  Call it AFTER all geometry is in the scene, or auto-fit measures the wrong bounds. Labels come afterwards and do not affect the fit.
- #ui is always docked as a right-side column by the scaffold and grows to fit its content. setUiLayout(...) exists only for backwards compatibility and cannot change the side, overlay state, or size. Just put controls in #ui. Never restyle #ui's position/width/max-height and never build your own side panel.
- addLabel(htmlString, THREE.Vector3, options?) — floating HTML label system.
- registerInteractive(object, { title, body, tooltip }), showPopup(title, body), hidePopup, showTooltip, hideTooltip — hover/click explanations.
- compileExpr(src, vars) → f(...args); throws on a bad expression (never returns a fallback)
- bindEquationInput(inputId, targets, { variables, onChange }) — wires an <input> to plot handles; shows parse errors inline
- plotCurve3D(id, { expr, variables, domain, plane:'xy'|'xz', samples, color }) → handle
- plotParametric3D(id, { x, y, z, variables, tDomain, samples, color }) → handle
- plotSurface(id, { expr, variables, xDomain, yDomain, segments, color }) → handle
  variables: the argument names the expression may use, in order (defaults: plotCurve3D ['x'], plotParametric3D ['t'], plotSurface ['x','y']). When a plan field declares "variables" you MUST pass that same array to BOTH the plot constructor and bindEquationInput — plotCurve3D('f', { expr: 't^2' }) without { variables: ['t'] } throws "Unknown variable t" at construction and kills the whole figure.
  Handles re-sample on EVERY setter call, and the setters differ: plotCurve3D → .setExpr / .setFn / .setDomain · plotParametric3D → .setX / .setY / .setZ · plotSurface → .setExpr / .setFn. All handles also have .sample() and .remove().
- Also pre-wired, do not re-declare: _labels, _syncLabels, animate, renderer, scene, camera, controls, d, aspect, setStandardView.

FIGURE RULES:
- Every visible element must be constructed as Three.js geometry (meshes, lines, points, sprites). Do NOT reproduce the figure as a texture, canvas drawing, or flat PlaneGeometry with the image drawn on it — pasting the original image onto a plane is never a valid solution.
- Keep the background white (#ffffff).
- The output should look recognizably like the source figure — same general geometry, viewpoint, labels, and proportions. It does not need to be a pixel-perfect same-size replacement.
- CAMERA / VIEW: camera pose is a standard default per projection mechanism, and PROJECTION TYPE in the user message gives the exact setCameraView call. Do not spend effort inferring exact angles from the source — spend it on ELEMENTS, geometry, and interactions. Align key visual anchors (object center, axes, labels) to similar relative positions as the source so the first frame is recognizable. You may adjust controls.target, object scale, and projection parameters; prefer setCameraView over setting camera.zoom directly, and if you do set zoom manually call camera.updateProjectionMatrix().
- Add ALL visible text labels with addLabel. Missing or wrong labels are a critical failure; match the source's font sizes and let placement reinforce depth.
- Interactions can be any type that serves the concept: sliders, buttons, panels, animations, step controls, hover/click, or direct 3D manipulation. Controls, panels, and UI affordances are welcome where they genuinely aid understanding — avoid decorative or redundant ones, but do not artificially restrict the type or amount of interaction.

ORDER OF WORK:
1) Settle the projection mechanism and pose from the plan BEFORE speccing any geometry — projection decides which edges stay parallel, which faces foreshorten, and what angle depth lines leave at.
2) Spec every element's Three.js primitive as one inline comment per element at the top of your JS block, e.g.
     // pinhole → SphereGeometry(0.07)  black
     // ray     → Line  dashed  grey
   Then build exactly that spec — do not deviate from it.
3) Build the static geometry. Preserve relative scale, spacing, depth ordering, and occlusion.
4) VERIFY before moving on: re-check what you built against GEOMETRY NOTES and the source image, element by element — position, orientation, proportions, and shape, not just presence. Fix any mismatch now; a generic-but-plausible arrangement that skips this check is the most common way geometry ends up wrong.
5) Then, in this order: setCameraView(...) → all labels → the plan's interactions.

userContent.text:
CONTEXT FROM TEXTBOOK:
This figure shows two identical cubic crystal lattices drawn side by side in perspective. Each is a three-by-three-by-three array of small red spheres standing for atoms, joined by thin black lines tracing the cube edges and the rows between nearest neighbors, so the block reads as open and transparent. In the left lattice, a translucent teal plane lies parallel to one pair of cube faces and passes through the middle sheet of atoms, appearing darker where it sits behind the front layer of spheres and paler where it emerges near the top face. In the right lattice, the highlighted plane is tilted instead, slicing diagonally from the lower left of the cube toward the upper right and intersecting a different set of spheres, its shading again splitting between a darker interior portion and a lighter one near the top. Holding the lattice fixed while changing only the orientation of the shaded plane makes that orientation the single variable in view. The pair conveys that one crystal holds many families of parallel atomic planes at differing angles and spacings, each able to produce its own X-ray diffraction.

PROJECTION TYPE: perspective
Use the scaffold's true perspective projection after building all geometry. Use this only when the source has real vanishing-point convergence or distance-based size shrinkage; then depth should visibly affect apparent size.

ELEMENTS TO RECREATE IN 3D:
  - 27 red atom spheres arranged in a 3x3x3 simple-cubic grid (indices 0,1,2 on each axis)
  - thin black line segments joining every pair of nearest-neighbor atoms along x, y, and z (the cube edges and interior rows)
  - outer cube silhouette formed by the edge lines so the block reads as open/transparent
  - one translucent teal atomic plane (double-sided quad) clipped to the cube bounding box
  - plane orientation controlled by Miller indices (h,k,l): face-parallel (100) vertical sheet, diagonal (110) sheet, steeper diagonal (111) sheet
  - plane offset index n selecting which parallel member of the family is highlighted (passes through a chosen sheet/diagonal row of atoms)
  - spacing label 'd = a / sqrt(h^2+k^2+l^2)' shown near the plane, updating with the family
  - small axis triad or x/y/z labels at the cube corner for orientation reference

GEOMETRY NOTES (world-space scale, color palette, and any formula/value needed for correctness — build to these so sizes, zoom, and colors match the source; do not guess dimensions the notes already specify):
Lattice constant a = 1 world unit; atoms at integer coords (i,j,k) with i,j,k in {0,1,2}, so the cube spans 0..2 on each axis (~2 units side). Atom spheres: SphereGeometry radius ~0.09, color #cc3333 with slight specular highlight. Bond lines: thin black (#111111) LineSegments between nearest neighbors only (|Δ|=1 along one axis). Teal plane color #5fb3a8, opacity ~0.45, DoubleSide, depthWrite false so spheres behind it stay visible (darker-through effect). Plane defined by Miller indices: normal = normalize(h,k,l), plane equation h*x+k*y+l*z = n, positioned at offset n/|n_vec| along the normal and clipped to the [0,2]^3 bounding box (build a large PlaneGeometry and intersect, or compute the convex polygon of the box-plane intersection). Family mapping: (100)->(1,0,0), (110)->(1,1,0), (111)->(1,1,1). d-spacing label value = 1/sqrt(h^2+k^2+l^2) (in units of a). Valid n that intersect atoms: (100): 0,1,2; (110): 0..4; (111): 0..6 — clamp slider n to the family's max so an empty plane is never shown. Default view matches the left source image (face-parallel middle sheet).

DISCRETE CONTROLS (implement every one of these in #ui, each must work independently):
[
  {
    "id": "planeFamily",
    "type": "toggle",
    "label": "Plane family (hkl)",
    "options": [
      "(100) face-parallel",
      "(110) diagonal",
      "(111) body-diagonal"
    ],
    "default": "(100) face-parallel",
    "teaches": "One fixed crystal contains many families of parallel atomic planes at different angles; rotating the highlighted plane through the same red-sphere lattice shows each family cuts a different set of atoms"
  },
  {
    "id": "planeIndex",
    "type": "slider",
    "label": "Plane index n",
    "range": [
      0,
      4,
      1
    ],
    "default": 1,
    "teaches": "Stepping n moves the translucent sheet to the next parallel plane in the chosen family, so successive sheets light up different rows of atoms and the d-spacing label ties orientation + spacing to the Bragg diffraction condition"
  }
]

DEMO STEPS (tween through these using goToStep(); each step drives the controls above):
[
  {
    "title": "Face-parallel (100) planes",
    "narration": "With (hkl)=(100) the teal sheet is parallel to a cube face and passes through the middle column of atoms (n=1). These are the widely spaced, face-on planes.",
    "state": {
      "planeFamily": "(100) face-parallel",
      "planeIndex": 1
    }
  },
  {
    "title": "Step to the next (100) plane",
    "narration": "Increase n to 2: the sheet jumps one lattice constant to the next parallel face-plane, highlighting the next row of spheres. Spacing d = a.",
    "state": {
      "planeFamily": "(100) face-parallel",
      "planeIndex": 2
    }
  },
  {
    "title": "Diagonal (110) family",
    "narration": "Switch the family to (110). The same lattice now shows a plane tilted 45° cutting diagonally through a different set of atoms; its spacing shrinks to d = a/√2.",
    "state": {
      "planeFamily": "(110) diagonal",
      "planeIndex": 2
    }
  },
  {
    "title": "Body-diagonal (111) family",
    "narration": "Switch to (111): an even steeper diagonal sheet with the tightest spacing d = a/√3, demonstrating that more steeply inclined families are more closely packed.",
    "state": {
      "planeFamily": "(111) body-diagonal",
      "planeIndex": 3
    }
  }
]

CAMERA VIEW (framing only). Call setCameraView({ projection, ...these }) AFTER all geometry is added. Keep the projection MECHANISM from PROJECTION TYPE above (orthographic / sheared-oblique / perspective). For perspective these params set the pose (azimuth/elevation/roll); for the two parallel projections pose is a standard default (see PROJECTION TYPE above), and these params set only roll and framing (heightFraction):
{
  "azimuthDeg": 35,
  "elevationDeg": 20,
  "rollDeg": 0,
  "heightFraction": 0.7
}

NOTES: Build the lattice once and keep it static; only the teal plane mesh and the d-spacing text update on interaction. Recompute the clipped plane polygon whenever planeFamily or planeIndex changes (hide the plane if n is out of the family's intersecting range). Render the spacing label as an HTML overlay or sprite anchored near the plane centroid. Use a subtle ambient + directional light so the red spheres read as 3D balls like the source. Keep orbit disabled (not requested) so the orientation variable stays unambiguous, matching the textbook's fixed-viewpoint comparison.

Follow the interaction plan above.

systemPrompt:
You are a strict critic of generated interactive Three.js 3D figures against original 2D textbook figure images.
You will receive the original source figure image, the generated HTML/JavaScript code, and a rendered screenshot of the generated HTML (if screenshot capture succeeds). Start by using the screenshot to help evaluate the faithfulness of the generated figure to the source figure, listing discrepancies in the primitive elements between what you see in the source figure versus what you see in the generated figure. If the screenshot was not received, mention this in the notes.
Score the generated figure using the rubric and give feedback to improve the figure. Be critical and honest — err toward lower scores when in doubt. Ensure that the output is not a 2D image rendered with Three.js. Do not give credit for things that are absent or barely present. Output ONLY a valid JSON object — no explanation, no markdown, no fences.

AUTOMATED VERIFICATION ALREADY PASSED. A deterministic verifier has rendered this figure headless at multiple viewports and confirmed it runs without exceptions or console errors with the render loop alive, actually draws to the GPU (non-blank canvas, real geometry, no NaN coordinates), fits the viewport with no overflow and the control panel fully on-screen, and has labels that are on-screen, not enormous, and not heavily overlapping.
Spend NO scores, failure modes, discrepancies, or action items on any of that. Focus ENTIRELY on SEMANTIC FIDELITY to the source: correct geometry, correct primitives, correct camera/view, faithful composition and colors, correct and meaningful labels, meaningful and conceptually-correct interactions, and concept accuracy. Judge whether it is the *right* figure and a good teaching artifact — not whether it renders.

SCAFFOLD CONTEXT (provided automatically — do not penalise for missing these):
- THREE, OrbitControls, renderer, scene, orthographic camera, controls, animate loop, ResizeObserver are all pre-wired
- addLabel(text, position3D, {color, fontSize, bold, offset, background}?) — floating HTML label system
- setStandardView({azimuth, polar, heightFraction}?) — frames the camera to scene content
- Reset View is scaffolded; generated code may add controls, panels, and UI affordances as needed to support the planned interactions

DISCREPANCIES - list 0-6 visual discrepancies between the source figure and the generated figure, prioritized by impact on recognizability and concept accuracy
- Focus on: wrong geometric primitives, missing or incorrect elements, wrong colors, missing or mislabeled annotations, broken or absent interactions
- De-prioritize: minor camera angle differences, exact crop/zoom, whitespace variation — only flag these if they make the figure hard to recognize or misleading
- For multipanel source figures, if the generated figure implements a toggle/tab/step between parts (e.g. Part A vs Part B), check the HTML/JS before flagging a part as "missing" — a part hidden behind an unactivated toggle is not a discrepancy

FAILURE MODES — list any that apply (use empty array [] if none):
"Depth-Wrong"             — 3D depth/perspective interpretation is incorrect
"Missing-Labels"          — important text annotations are absent
"Wrong-Primitives"        — incorrect geometric shapes used for the concept
"Interaction-Broken"      — interactive controls are present but non-functional
"Interaction-Missing"     — no meaningful interactions beyond basic OrbitControls rotation
"Camera-Wrong"            — initial viewpoint differs from the source figure — wrong angle/orientation/rotation, even if all content remains visible
"Scale-Wrong"             — element proportions are noticeably off
"Color-Wrong"             — colors don't match the original figure
"Hallucination"           — elements present that do not appear in the original
"Concept-Misunderstood"   — the core concept being illustrated is    misrepresented

SCORES — integer 1–5 for each field:
geometry_accuracy — Judge these five things:
  • CAMERA — flag "Camera-Wrong" only if the vantage point differs enough to make the figure hard to recognize (reversed foreground/background, a key face hidden, viewed from the opposite side). Minor azimuth/zoom differences do not qualify.
  • PRIMITIVES — flag "Wrong-Primitives" and cap the score when a major element uses the wrong shape (a box drawn as a cone/pyramid, a plane as a disc, a ray as a thick cylinder), even if the composition looks similar.
  • PROJECTION MECHANISM — axonometric = off-axis orthographic, no shear; oblique = front-on orthographic plus a consistent depth shear; perspective = true perspective, used when the source shows convergence or distance-based shrinking.
  • REPEATED ELEMENTS — compare each corresponding element's size and proportions to the source, not just its presence. A set that should visibly vary in size but came out uniform is a spatial error, even if each element is individually a plausible primitive.
  • HARD FLOOR — if the source has genuine 3D structure (elements at different depths, occlusion, a meaningfully three-dimensional arrangement) but the generated figure flattened it into a camera-facing poster with no occlusion or depth falloff, score geometry_accuracy 1 and include "Depth-Wrong", regardless of how correct the colors/labels/elements are. Does NOT apply when the source is itself a flat 2D diagram the plan correctly renders front-on (axis_screen_angles: null).
  5 – All elements represented; plausible positions, connections, proportions
  4 – All major elements present; minor position/alignment issues
  3 – 1-2 elements missing OR noticeable spatial errors; concept still recognizable
  2 – Multiple missing elements OR major spatial errors
  1 – Unrecognizable or completely wrong topology

interactivity_usability — CRITICAL: OrbitControls (mouse drag to rotate/zoom) does NOT count as an interaction. Meaningful interactions = buttons, sliders, toggles, step-through animations, parameter controls built by the developer.
  5 – All planned interactions functional and pedagogically useful; count matches figure complexity (1 deep slider is correct for a single-variable concept; 3+ expected for multi-step figures); demo steps present if the plan includes them
  4 – Most planned interactions functional; minor usability issues; pedagogical value clear
  3 – At least one meaningful interaction works; some planned interactions missing or broken; or interactions only weakly connected to the concept
  2 – Interactions exist in code but broken or no visible effect
  1 – Only OrbitControls present, or no interactions at all — score MUST be 1

faithfulness — Judge overall visual resemblance to the source — composition, geometry, and color scheme at a glance — rather than an exhaustive checklist of small differences. For multipanel source figures where the generated figure implements a toggle/tab/step between parts (e.g. Part A vs Part B), it is correct and expected for only one part to be visible in the default screenshot; check the HTML/JS for a toggle control before penalizing a currently-hidden part as missing or absent. Do not over-penalize extra elements added beyond the source (additional UI chrome, decorative touches) unless they clutter the figure or change its overall look — flag those under the Hallucination failure mode rather than cutting this score for minor additions.
  5 – Clearly recognizable as the same figure: correct geometry, colors, composition, and major labels all present
  4 – Recognizable at a glance; minor differences in color, proportion, or label placement
  3 – General idea clear but notable differences in geometry, composition, or missing elements
  2 – Hard to recognize as the same figure; significant content differences
  1 – Completely different or fabricated

label_quality — Off-screen / heavily-overlapping labels are already caught by the verifier — do not re-flag those. Judge CONTENT (right labels present, correct text, on the correct element, matching the source) and LEGIBILITY (comfortably readable even when the verifier did not call them "enormous", with a deliberate hierarchy — primary labels standing out over axis labels — matching what the source implies).
  5 – All the right labels present, correct text on the correct elements, matching the source, AND sized/styled for easy legibility with a clear hierarchy matching the source
  4 – Content correct; only 1-2 minor issues (content OR sizing/hierarchy — e.g. a label slightly too small or inconsistently sized)
  3 – Half of labels have issues, whether content (wrong text, wrong target, missing, unclear) or legibility (uncomfortably small, inconsistent hierarchy)
  2 – Most labels problematic — mislabeled/missing content, or generally too small/cluttered to read comfortably
  1 – No labels, or all wrong/mislabeled/illegible

concept_accuracy:
  5 – All concepts accurate; interactions demonstrate correct relationships; no misinformation
  4 – Main concept correct; ≤1 minor detail wrong or missing
  3 – Main concept present; 2-3 details wrong or missing
  2 – Significant errors or fabrications; would mislead students
  1 – Completely incorrect or misleading

ACTION ITEMS — separate feedback for the generation and the plan:
- action_items: list 2-4 generation-level fixes (broken controls, wrong primitives, missing labels, scale issues, camera/view correction — things fixable without changing the plan)
- plan_action_items: list 0-2 plan-level fixes (wrong projection_type, missing core elements, wrong interaction type for the concept, fundamental misunderstanding — things requiring a revised plan). Use [] if the plan is sound.

