    }
  }
}

// ── Bond lines (nearest neighbors) ──
const bondPositions = [];
for (let i = 0; i < 3; i++) {
  for (let j = 0; j < 3; j++) {
    for (let k = 0; k < 3; k++) {
      if (i < 2) { bondPositions.push(i,j,k, i+1,j,k); }
      if (j < 2) { bondPositions.push(i,j,k, i,j+1,k); }
      if (k < 2) { bondPositions.push(i,j,k, i,j,k+1); }
    }
