// @FIGURE_CODE_BEGIN
// ── Element specs ──
// atom sphere → SphereGeometry(0.09, 16, 12), MeshPhongMaterial #cc3333, shininess 60
// bond lines → LineSegments, LineBasicMaterial #111111
// primary teal plane → BufferGeometry triangle fan, MeshBasicMaterial #5fb3a8, opacity 0.45, DoubleSide, depthWrite:false, renderOrder:10
// secondary teal plane (right lattice) → same geometry approach, opacity 0.30, renderOrder:10
// NO axis labels, NO plane text labels (source is unannotated)
// lights → AmbientLight 0.5 + DirectionalLight 0.7

// ── Lights ──
const ambLight = new THREE.AmbientLight(0xffffff, 0.5);
scene.add(ambLight);
const dirLight = new THREE.DirectionalLight(0xffffff, 0.7);
dirLight.position.set(3, 5, 4);
scene.add(dirLight);

// ── Lattice builder ──
const atomGeo = new THREE.SphereGeometry(0.09, 16, 12);
const atomMat = new THREE.MeshPhongMaterial({ color: 0xcc3333, shininess: 60, specular: 0x444444 });
const allAtoms = [];

function buildLattice(xOffset) {
  const atoms = [];
  for (let i = 0; i < 3; i++) {
    for (let j = 0; j < 3; j++) {
      for (let k = 0; k < 3; k++) {
        const mesh = new THREE.Mesh(atomGeo, atomMat);
        mesh.position.set(i + xOffset, j, k);
        scene.add(mesh);
        atoms.push(mesh);
        allAtoms.push(mesh);
      }
    }
  }
  // Bond lines
  const bondPositions = [];
  for (let i = 0; i < 3; i++) {
    for (let j = 0; j < 3; j++) {
      for (let k = 0; k < 3; k++) {
        const x = i + xOffset;
        if (i < 2) bondPositions.push(x, j, k, x + 1, j, k);
        if (j < 2) bondPositions.push(x, j, k, x, j + 1, k);
        if (k < 2) bondPositions.push(x, j, k, x, j, k + 1);
      }
    }
  }
  const bondGeo = new THREE.BufferGeometry();
  bondGeo.setAttribute('position', new THREE.Float32BufferAttribute(bondPositions, 3));
  const bondMat = new THREE.LineBasicMaterial({ color: 0x111111 });
  const bonds = new THREE.LineSegments(bondGeo, bondMat);
  scene.add(bonds);
  return atoms;
}

// Left lattice (primary, UI-controlled plane)
const leftAtoms = buildLattice(0);
// Right lattice (reference, fixed diagonal plane)
const rightAtoms = buildLattice(3.5);

// ── Plane clipping ──
function computePlanePolygon(h, k, l, n, xOff) {
  const edges = [
    [[0,0,0],[2,0,0]], [[0,2,0],[2,2,0]], [[0,0,2],[2,0,2]], [[0,2,2],[2,2,2]],
    [[0,0,0],[0,2,0]], [[2,0,0],[2,2,0]], [[0,0,2],[0,2,2]], [[2,0,2],[2,2,2]],
    [[0,0,0],[0,0,2]], [[2,0,0],[2,0,2]], [[0,2,0],[0,2,2]], [[2,2,0],[2,2,2]]
  ];
  const pts = [];
  for (const [A, B] of edges) {
    const a0 = A[0] + xOff, b0 = B[0] + xOff;
    const dA = h * a0 + k * A[1] + l * A[2];
    const dB = h * b0 + k * B[1] + l * B[2];
    const denom = dB - dA;
    if (Math.abs(denom) < 1e-10) continue;
    const t = (n - dA) / denom;
    if (t >= -1e-9 && t <= 1 + 1e-9) {
      const tc = Math.max(0, Math.min(1, t));
      pts.push(new THREE.Vector3(
        a0 + tc * (b0 - a0),
        A[1] + tc * (B[1] - A[1]),
        A[2] + tc * (B[2] - A[2])
      ));
    }
  }
  const unique = [];
  for (const p of pts) {
    let dup = false;
    for (const q of unique) { if (p.distanceTo(q) < 1e-6) { dup = true; break; } }
    if (!dup) unique.push(p);
  }
  if (unique.length < 3) return null;
  const centroid = new THREE.Vector3();
  for (const p of unique) centroid.add(p);
  centroid.divideScalar(unique.length);
  const normal = new THREE.Vector3(h, k, l).normalize();
  let u = new THREE.Vector3(1, 0, 0);
  if (Math.abs(normal.dot(u)) > 0.9) u = new THREE.Vector3(0, 1, 0);
  u.sub(normal.clone().multiplyScalar(normal.dot(u))).normalize();
  const v = new THREE.Vector3().crossVectors(normal, u).normalize();
  unique.sort((a, b) => {
    const da = a.clone().sub(centroid);
    const db = b.clone().sub(centroid);
    return Math.atan2(da.dot(v), da.dot(u)) - Math.atan2(db.dot(v), db.dot(u));
  });
  return { points: unique, centroid, normal };
}

function buildPlaneMesh(mesh, h, k, l, n, xOff) {
  const result = computePlanePolygon(h, k, l, n, xOff);
  if (!result) { mesh.visible = false; return null; }
  const { points, centroid } = result;
  const positions = [centroid.x, centroid.y, centroid.z];
  const indices = [];
  for (const p of points) positions.push(p.x, p.y, p.z);
  for (let i = 0; i < points.length; i++) {
    indices.push(0, i + 1, ((i + 1) % points.length) + 1);
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geo.setIndex(indices);
  geo.computeVertexNormals();
  const old = mesh.geometry;
  mesh.geometry = geo;
  old?.dispose?.();
  mesh.visible = true;
  return result;
}

// ── Primary plane (left lattice) ──
const planeMat = new THREE.MeshBasicMaterial({
  color: 0x5fb3a8, opacity: 0.45, transparent: true,
  side: THREE.DoubleSide, depthWrite: false
});
const planeMesh = new THREE.Mesh(new THREE.BufferGeometry(), planeMat);
planeMesh.renderOrder = 10;
scene.add(planeMesh);

// ── Secondary plane (right lattice, fixed (110) n=2) ──
const planeMat2 = new THREE.MeshBasicMaterial({
  color: 0x5fb3a8, opacity: 0.30, transparent: true,
  side: THREE.DoubleSide, depthWrite: false
});
const planeMesh2 = new THREE.Mesh(new THREE.BufferGeometry(), planeMat2);
planeMesh2.renderOrder = 10;
scene.add(planeMesh2);

// ── State ──
const FAMILIES = {
  '(100) face-parallel': { h: 1, k: 0, l: 0, maxN: 2 },
  '(110) diagonal': { h: 1, k: 1, l: 0, maxN: 4 },
  '(111) body-diagonal': { h: 1, k: 1, l: 1, maxN: 6 }
};
let currentFamily = '(100) face-parallel';
let currentN = 1;

function updatePlane() {
  const fam = FAMILIES[currentFamily];
  const clampedN = Math.min(currentN, fam.maxN);
  buildPlaneMesh(planeMesh, fam.h, fam.k, fam.l, clampedN, 0);
  // Right lattice always shows (110) n=2 as reference comparison
  buildPlaneMesh(planeMesh2, 1, 1, 0, 2, 3.5);
  // Update d-spacing display
  const dVal = 1 / Math.sqrt(fam.h * fam.h + fam.k * fam.k + fam.l * fam.l);
  document.getElementById('dSpacing').textContent =
    `d = a / √(${fam.h}²+${fam.k}²+${fam.l}²) = ${dVal.toFixed(3)} a`;
  document.getElementById('nVal').textContent = clampedN;
  const slider = document.getElementById('planeIndex');
  slider.max = fam.maxN;
  slider.value = clampedN;
}

// ── UI Controls ──
const famBtnIds = {
  '(100) face-parallel': 'fam100',
  '(110) diagonal': 'fam110',
  '(111) body-diagonal': 'fam111'
};

function setFamily(name) {
  currentFamily = name;
  for (const [key, id] of Object.entries(famBtnIds)) {
    document.getElementById(id).classList.toggle('active', key === name);
  }
  updatePlane();
}

for (const [name, id] of Object.entries(famBtnIds)) {
  document.getElementById(id).addEventListener('click', () => setFamily(name));
}

document.getElementById('planeIndex').addEventListener('input', (e) => {
  currentN = parseInt(e.target.value);
  updatePlane();
});

// Initial build
updatePlane();

// ── Interactive registration ──
for (const atom of allAtoms) {
  registerInteractive(atom, {
    title: 'Atom',
    body: 'A lattice point in the simple cubic crystal. Each red sphere represents one atom at an integer coordinate.',
    tooltip: 'Atom (lattice point)'
  });
}
registerInteractive(planeMesh, {
  title: 'Atomic plane',
  body: 'A family of parallel planes defined by Miller indices (hkl). The plane equation is hx+ky+lz=n. Different families have different orientations and spacings, producing different X-ray diffraction patterns.',
  tooltip: 'Click to learn about atomic planes'
});

// ── Camera ──
setCameraView({
  projection: 'perspective',
  azimuthDeg: 35,
  elevationDeg: 20,
  rollDeg: 0,
  heightFraction: 0.7,
  target: [2.75, 1, 1]
});

// ── Demo steps ──
const DEMO_STEPS = [
  {
    title: 'Face-parallel (100) planes',
    narration: 'With (hkl)=(100) the teal sheet is parallel to a cube face and passes through the middle column of atoms (n=1). These are the widely spaced, face-on planes.',
    state: { planeFamily: '(100) face-parallel', planeIndex: 1 }
  },
  {
    title: 'Step to the next (100) plane',
    narration: 'Increase n to 2: the sheet jumps one lattice constant to the next parallel face-plane, highlighting the next row of spheres. Spacing d = a.',
    state: { planeFamily: '(100) face-parallel', planeIndex: 2 }
  },
  {
    title: 'Diagonal (110) family',
    narration: 'Switch the family to (110). The same lattice now shows a plane tilted 45° cutting diagonally through a different set of atoms; its spacing shrinks to d = a/√2.',
    state: { planeFamily: '(110) diagonal', planeIndex: 2 }
  },
  {
    title: 'Body-diagonal (111) family',
    narration: 'Switch to (111): an even steeper diagonal sheet with the tightest spacing d = a/√3, demonstrating that more steeply inclined families are more closely packed.',
    state: { planeFamily: '(111) body-diagonal', planeIndex: 3 }
  }
];

let demoRunning = false;
let demoStepIdx = 0;

function goToStep(idx) {
  if (idx < 0 || idx >= DEMO_STEPS.length) return;
  const step = DEMO_STEPS[idx];
  currentFamily = step.state.planeFamily;
  currentN = step.state.planeIndex;
  for (const [key, id] of Object.entries(famBtnIds)) {
    document.getElementById(id).classList.toggle('active', key === currentFamily);
  }
  updatePlane();
  showPopup(step.title, step.narration);
}

document.getElementById('btnDemo').addEventListener('click', () => {
  if (demoRunning) return;
  demoRunning = true;
  demoStepIdx = 0;
  const runNext = () => {
    if (demoStepIdx >= DEMO_STEPS.length) {
      demoRunning = false;
      hidePopup();
      return;
    }
    goToStep(demoStepIdx);
    demoStepIdx++;
    setTimeout(runNext, 3500);
  };
  runNext();
});

window.goToStep = goToStep;
// @FIGURE_CODE_END

