// @FIGURE_CODE_BEGIN
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));

const state = {
  rotationCamera2: 0,
  translationCamera2: 0,
  activeStep: 0,
  tween: null
};

const BLACK = 0x111318;
const SOFT_BLACK = 0x1b1d22;
const RED = 0xff1010;
const GREEN = 0x22e000;
const BLUE = 0x2878ff;
const CYAN = 0x60f3ef;
const MAGENTA = 0xff76b7;
const WHITE = 0xffffff;

const fixedGroup = new THREE.Group();
const dynamicGroup = new THREE.Group();
scene.add(fixedGroup, dynamicGroup);

const worldUp = new THREE.Vector3(0, 1, 0);
const C1 = new THREE.Vector3(-4.65, -1.65, -0.12);
const P = new THREE.Vector3(0.75, 1.95, 0.56);
const rayDir1 = new THREE.Vector3().subVectors(P, C1).normalize();

// [elided] disposeGroup / makeBasisFromNormal / addCylinderBetween / addConeAt — generic mesh plumbing
function addArrow(parent, origin, dir, length, color, radius = 0.022, headScale = 1) {
  const d0 = dir.clone().normalize();
  const headH = Math.min(0.38 * headScale, Math.max(0.15, length * 0.26));
  const shaftEnd = origin.clone().addScaledVector(d0, Math.max(length - headH * 0.72, 0.01));
  const tip = origin.clone().addScaledVector(d0, length);
  addCylinderBetween(parent, origin, shaftEnd, radius, color, 1, 16);
  addConeAt(parent, tip, d0, radius * 5.7 * headScale, headH, color);
  return tip;
}

// [elided] addDashedSegment / addThickPolyline / addPlanePatch
// [elided] addPlaneOutline(parent, center, normal, w, h, color, radius) -> { corners, u, v, center, normal, width, height }
function addCamera(parent, center, planeCorners, facingDir, labelSide = 1) {
  const body = new THREE.Mesh(
    new THREE.SphereGeometry(0.22, 40, 20),
    new THREE.MeshBasicMaterial({ color: BLACK })
  );
  body.position.copy(center);
  parent.add(body);

  const aperture = new THREE.Mesh(
    new THREE.SphereGeometry(0.12, 32, 16),
    new THREE.MeshBasicMaterial({ color: 0x000000 })
  );
  aperture.position.copy(center).addScaledVector(facingDir.clone().normalize(), 0.035);
  parent.add(aperture);

  for (const c of planeCorners) addCylinderBetween(parent, center, c, 0.021, BLACK, 1, 14);

  const base = center.clone().add(new THREE.Vector3(0.34 * labelSide, 0.00, -0.06));
  addCylinderBetween(parent, center, base, 0.03, BLACK, 1, 14);
}

// [elided] addPoint / projectFromCameraToPlane / clipLineToPlaneRect / addCurvedArrow / setSerif(labelEntry, weight)
const plane1Normal = rayDir1.clone();
const basis1 = makeBasisFromNormal(plane1Normal);
const p1 = C1.clone().addScaledVector(rayDir1, 2.78);
const plane1Center = p1.clone()
  .addScaledVector(basis1.u, -0.60)
  .addScaledVector(basis1.v, 0.06);

const plane1 = addPlaneOutline(fixedGroup, plane1Center, plane1Normal, 3.05, 3.62, BLACK, 0.029);
addCamera(fixedGroup, C1, plane1.corners, plane1Normal, 1);

const rayEnd = C1.clone().addScaledVector(rayDir1, 8.75);
addCylinderBetween(fixedGroup, C1, rayEnd, 0.052, RED, 1, 24);
addPoint(fixedGroup, p1, RED, 0.115);
addPoint(fixedGroup, P, CYAN, 0.12);

const axisOrigin1 = plane1Center.clone().addScaledVector(plane1Normal, 0.10);
const x1Tip = addArrow(fixedGroup, axisOrigin1, plane1.u.clone().multiplyScalar(-1), 1.13, GREEN, 0.019, 0.92);
const y1Tip = addArrow(fixedGroup, axisOrigin1, plane1.v, 1.16, GREEN, 0.019, 0.92);
const z1Tip = addArrow(fixedGroup, axisOrigin1, plane1Normal, 0.93, GREEN, 0.019, 0.92);

function camera2Center() {
  return new THREE.Vector3(
    4.20 + state.translationCamera2 * 0.18,
    -1.62,
    0.08 + state.translationCamera2 * 0.052
  );
}

function camera2Normal() {
  const base = new THREE.Vector3(-1.66, 0.78, 0.08).normalize();
